# Different rule: Find connected regions of 0s that are bounded by markers (7)
# Use flood fill from each corner to find unbounded 0s, then fill bounded 0s

def solve_bounded_regions(grid):
    result = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Mark all 0s reachable from top-left as "unbounded"
    queue = [(0, 0)]
    visited = set([(0, 0)])
    unbounded_0s = {0}

    r, c = 0, 0
    if grid[r][c] == 0:
        while queue:
            cr, cc = queue.pop(0)
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if (nr, nc) not in visited and grid[nr][nc] == 0:
                        visited.add((nr, nc))
                        queue.append((nr, nc))
                        unbounded_0s.add(nr * w + nc)

    # Also check all boundaries
    boundary_zeros_reachable = True
    for r in range(h):
        for c in range(w):
            if (r, c) not in visited and grid[r][c] == 0:
                queue.append((r, c))
                visited.add((r, c))
                unbounded_0s.add(r * w + c)

    # Fill all 0s that are NOT reachable from the boundary
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r, c) not in visited:
                result[r][c] = 7

    return result

