# Try finding bounding boxes of non-zero markers
# For each position, check if there's a marker above AND below AND left AND right

def is_within_marker_box(grid, pos):
    """Check if position is within a bounding box defined by markers"""
    r, c = pos

    # Find nearest non-zero in each direction
    def find_nearest_nonzero(row_idx, col_start, col_end):
        if col_start >= col_end:
            return None
        candidates = [(i, grid[row_idx][i]) for i in range(col_start, col_end)]
        if candidates:
            return min(candidates, key=lambda x: abs(x[1]))
        return None

    def find_nearest_above_or_below(r, c, dist=5):
        for dr in range(1, dist+1):
            found = []
            for dc in range(-2, 3):
                nr, nc = r - dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    if grid[nr][nc] != 0:
                        found.append((nr, nc))
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    if grid[nr][nc] != 0:
                        found.append((nr, nc))
            if found:
                return sorted(found)[:1]
        return None

    above = find_nearest_above_or_below(r, c, 5)
    below = find_nearest_above_or_below(r, c, 5)
    left_found = False
    right_found = False

    for dc in range(1, min(c+1, 5)+1):
        if grid[r][c-dc] != 0:
            left_found = True
            break
    for dc in range(1, min(len(demo_input[0])-c, 5)+1):
        if grid[r][c+dc] != 0:
            right_found = True
            break

    return bool(above and below and left_found and right_found)

